def parse_directive_content(self, block: 'BlockParser', m: Match[str],
    state: 'BlockState') ->Optional[List[Dict[str, Any]]]:
    content = self.parse_content(m)
    if not content:
        return None

    tokens = list(self.parse_tokens(block, content, state))
    caption = tokens[0]
    if caption['type'] == 'paragraph':
        caption['type'] = 'figcaption'
        children = [caption]
        if len(tokens) > 1:
            children.append({
                'type': 'legend',
                'children': tokens[1:]
            })
        return children
    return None
